def evaluate_expression(expr):
    try:
        # Handle operator precedence and parentheses
        # Using eval is safe here because the input is restricted to integers, operators, and parentheses
        result = eval(expr)
        if isinstance(result, int):
            return str(result)
        else:
            return "{0:.6f}".format(result)
    except:
        return None

