import sys
import subprocess
import shlex
import math

def process_line(line):
    stripped = line.strip()
    if not stripped:
        return

    if stripped.startswith('run '):
        cmd = stripped[4:]
        try:
            result = subprocess.run(cmd, shell=True, check=True, text=True, capture_output=True)
            sys.stdout.write(result.stdout + result.stderr)
        except subprocess.CalledProcessError as e:
            pass
    elif stripped.startswith('calc '):
        expr = stripped[5:]
        try:
            # Handle integer evaluation
            try:
                result = eval(expr)
                if isinstance(result, int):
                    sys.stdout.write(str(result))
                else:
                    sys.stdout.write(f"{result:.6f}")
            except:
                pass
            # Fallback to float evaluation if integer fails
            try:
                result = float(expr)
                sys.stdout.write(f"{result:.6f}")
            except:
                pass
        except Exception:
            pass
    else:
        sys.stdout.write(f"ERROR: {line}")

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    with open(sys.argv[1], 'r') as file:
        for line in file:
            process_line(line)

if __name__ == "__main__":
    main()

